function lessonStatus(v){const raw=String(v??'');if(/[✓✔☑]/.test(raw))return 'Completed';const t=norm(raw);if(!t)return null;if(/not yet|nyc|\bnys\b|in progress|incomplete|repeat|partial|unsat|not satisfactory|not competent|^(r|u|f|fail|failed|no|n)$/.test(t))return 'In progress';if(/^(c|comp|completed?|competent|s|sat|satisfactory|pass|passed|p|yes|y|done|ok|true|x|achieved|flown|signed off|cleared)$/.test(t)||/\b(competent|completed?|satisfactory|passed|achieved|signed off)\b/.test(t))return 'Completed';if(/not started|not attempted/.test(t))return 'Not started';return null}
